import{_ as e,c as t,o as s,b0 as i}from"./chunks/framework.C5ev1SXp.js";const b=JSON.parse('{"title":"LV020-硬件I2C与FSMC的PB7引脚冲突","description":null,"frontmatter":{"title":"LV020-硬件I2C与FSMC的PB7引脚冲突","date":"2026-11-01T14:20:20.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/peripheral/i2c/126d67bc80042951e1b522cd","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-11-01T14:20:20.661Z","fulluuid":"1e1b522cd9a34a40be9172c7e1834093","useduuid":"1e1b522cd"}},"headers":[],"relativePath":"sdoc/peripheral/i2c/126d67bc80042951e1b522cd.md","filePath":"sdoc/20-基本外设篇/30-I2C/LV020-硬件I2C与FSMC的PB7引脚冲突.md","lastUpdated":1793515252000}'),r={name:"sdoc/peripheral/i2c/126d67bc80042951e1b522cd.md"};function n(d,a,l,o,h,c){return s(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="lv020-硬件i2c与fsmc的pb7引脚冲突" tabindex="-1">LV020-硬件I2C与FSMC的PB7引脚冲突 <a class="header-anchor" href="#lv020-硬件i2c与fsmc的pb7引脚冲突" aria-label="Permalink to &quot;LV020-硬件I2C与FSMC的PB7引脚冲突&quot;">​</a></h1><h2 id="一、-问题现象" tabindex="-1">一、 问题现象 <a class="header-anchor" href="#一、-问题现象" aria-label="Permalink to &quot;一、 问题现象&quot;">​</a></h2><h3 id="_1-硬件连接" tabindex="-1">1. 硬件连接 <a class="header-anchor" href="#_1-硬件连接" aria-label="Permalink to &quot;1. 硬件连接&quot;">​</a></h3><p>战舰 V3 上的 AT24C02 挂在 PB6/PB7，正是 I2C1 的默认引脚：<a href="https://cnb.cool/sumu.m/scm-reference-guide/-/git/raw/main/30-STM32%E8%B5%84%E6%96%99/01-ATK%E6%88%98%E8%88%B0-V3%E5%BC%80%E5%8F%91%E6%9D%BF%E5%8E%9F%E7%90%86%E5%9B%BE/WarShip%20STM32F1_V3.4_SCH.pdf" target="_blank" rel="noreferrer">原理图</a> 第 3 页 EEPROM 区显示 SCL 接 PB6、SDA 接 PB7，A0~A2 与 WP 全部接地。按 <a href="./LV015-AT24C02使用实例.html">LV015-AT24C02使用实例</a> 里的 HAL 硬件 I2C 流程写完驱动后，读 EEPROM 的每一次调用都超时返回 <code>HAL_ERROR</code>。</p><h3 id="_2-实测表现" tabindex="-1">2. 实测表现 <a class="header-anchor" href="#_2-实测表现" aria-label="Permalink to &quot;2. 实测表现&quot;">​</a></h3><p>用寄存器级 trace（直接读 <code>I2C1-&gt;CR1</code>、<code>SR1</code>、<code>SR2</code>）看到的并不是“从机不应答”，而是更靠前的一步就卡死了：</p><table tabindex="0"><thead><tr><th>观测点</th><th>现象</th></tr></thead><tbody><tr><td>置 <code>CR1.START</code> 后轮询 <code>SR1.SB</code></td><td>永远为 0</td></tr><tr><td>轮询期间读引脚状态</td><td>SDA、SCL 都静止，没有任何翻转</td></tr><tr><td>同一份代码把 I2C1 重映射到 PB8/PB9</td><td><code>SB</code> 立刻置位，START 正常发出</td></tr></tbody></table><p>前两行说明主机连起始条件都没发出去，第三行说明外设本身是好的——问题出在 PB7 这根线被别人占住了。</p><h2 id="二、-原因分析" tabindex="-1">二、 原因分析 <a class="header-anchor" href="#二、-原因分析" aria-label="Permalink to &quot;二、 原因分析&quot;">​</a></h2><h3 id="_1-pb7-的复用冲突" tabindex="-1">1. PB7 的复用冲突 <a class="header-anchor" href="#_1-pb7-的复用冲突" aria-label="Permalink to &quot;1. PB7 的复用冲突&quot;">​</a></h3><p>STM32F103ZE 上 PB7 的复用功能不止 I2C1_SDA，复用功能表见 <a href="https://cnb.cool/sumu.m/scm-reference-guide/-/git/raw/main/30-STM32%E8%B5%84%E6%96%99/STM32F103xCDE_DS_CH_V5.pdf" target="_blank" rel="noreferrer">数据手册</a> 第 3 章 Pinouts and pin descriptions：</p><table tabindex="0"><thead><tr><th>引脚</th><th>复用功能</th><th>本板占用情况</th></tr></thead><tbody><tr><td>PB6</td><td>I2C1_SCL / TIM4_CH1</td><td>只与 TIM4 冲突，本板没用 TIM4</td></tr><tr><td>PB7</td><td>I2C1_SDA / TIM4_CH2 / <strong>FSMC_NADV</strong></td><td>与 FSMC 的地址锁存信号撞车</td></tr></tbody></table><p>关键在 FSMC 是“上电即占用”：<code>FSMC_BCR1</code> 的复位值是 <code>0x0000_30DB</code>，其中 <code>MBKEN = 1</code>、<code>MUXEN = 1</code>，即复位后 Bank1 已经使能、且工作在复用（NOR/PSRAM）模式。本板 LCD 与外部 SRAM 都挂在 FSMC 上，时钟必须常开。此时 NADV 作为 FSMC 输出被配成复用推挽，空闲时默认输出高电平，把 SDA 钉死在高电平，I2C1 的开漏下拉根本拉不动它，自然永远等不到 <code>SB</code>。</p><p>FSMC 一侧的结构见 <a href="/scm-docs/sdoc/peripheral/fsmc/fsmc-basic/126b092492553b23e8704ba7.html">LV001-FSMC简介</a>，信号定义见 <a href="/scm-docs/sdoc/peripheral/fsmc/fsmc-basic/126b092499b000721416c9a0.html">LV005-存储器映射与控制器</a>，LCD 用 FSMC 模拟 8080 时序的例子见 <a href="/scm-docs/sdoc/advanced-chapter/display/lcd/126b09523c371707f0bd772f.html">LV020-FSMC模拟8080时序</a>。</p><h3 id="_2-官方勘误的定性" tabindex="-1">2. 官方勘误的定性 <a class="header-anchor" href="#_2-官方勘误的定性" aria-label="Permalink to &quot;2. 官方勘误的定性&quot;">​</a></h3><p><a href="https://cnb.cool/sumu.m/scm-reference-guide/-/git/raw/main/30-STM32%E8%B5%84%E6%96%99/15-STM32%E5%8B%98%E8%AF%AF%E6%89%8B%E5%86%8C/STM32F10xxCDE_Errata_CH_V5.pdf" target="_blank" rel="noreferrer">《STM32F10xxCDE 勘误手册》V5</a> 第 2.4.9 节「FSMC 和 I2C1 以及 TIM4_CH2」原文（中译）：</p><blockquote><p>当使用 FSMC 功能时，NADV 被配置成复用输出，该信号会被默认地置位为 &#39;1&#39;，这样就和 TIM4_CH2 和 I2C1 的 SDA 信号发生冲突。</p><p>暂时解决办法：当使用 FSMC 的同时，不要使用 TIM4_CH2 作为输出。如果要使用 I2C1 并且封装允许，就把该功能重映射到 PB8/PB9。</p></blockquote><p>对照本板，官方给的两条出路：</p><table tabindex="0"><thead><tr><th>官方出路</th><th>本板可行性</th></tr></thead><tbody><tr><td>做 FSMC 时不用 TIM4_CH2 输出</td><td>与 EEPROM 无关，解决不了问题</td></tr><tr><td>I2C1 重映射到 PB8/PB9</td><td>24C02 的 SCL/SDA 焊死在 PB6/PB7，除非飞线改板</td></tr></tbody></table><p>一条不相关、一条要动硬件，剩下的只有参考手册里的另一个软件开关。</p><h3 id="_3-afio-mapr2-逃生通道失效" tabindex="-1">3. AFIO_MAPR2 逃生通道失效 <a class="header-anchor" href="#_3-afio-mapr2-逃生通道失效" aria-label="Permalink to &quot;3. AFIO_MAPR2 逃生通道失效&quot;">​</a></h3><h4 id="_3-1-寄存器定义" tabindex="-1">3.1 寄存器定义 <a class="header-anchor" href="#_3-1-寄存器定义" aria-label="Permalink to &quot;3.1 寄存器定义&quot;">​</a></h4><p><a href="https://cnb.cool/sumu.m/scm-reference-guide/-/git/raw/main/30-STM32%E8%B5%84%E6%96%99/STM32%E8%8B%B1%E6%96%87%E5%8F%82%E8%80%83%E6%89%8B%E5%86%8C_V15.pdf" target="_blank" rel="noreferrer">《STM32 英文参考手册》V15</a> 第 9.4.7 节「AF remap and debug I/O configuration register2（AFIO_MAPR2）」，偏移 <code>0x1C</code>：</p><blockquote><p>Bit 10 FSMC_NADV: NADV connect/disconnect This bit is set and cleared by software. It controls the use of the optional FSMC_NADV signal. 0: The NADV signal is connected to the output (default) 1: The NADV signal is not connected. The I/O pin can be used by another peripheral.</p></blockquote><p>按手册，往 <code>AFIO-&gt;MAPR2</code> 的 bit10 写 1 就能断开 NADV、把 PB7 还给 I2C1，CubeMX 生成的 <code>__HAL_AFIO_FSMCNADV_DISCONNECTED()</code> 做的正是这件事。</p><h4 id="_3-2-实测结果" tabindex="-1">3.2 实测结果 <a class="header-anchor" href="#_3-2-实测结果" aria-label="Permalink to &quot;3.2 实测结果&quot;">​</a></h4><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// flash-app/Drivers/BSP/EEPROM（诊断代码，结论确认后已删除）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AFIO</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MAPR2 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">00000400</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">U</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   /* bit10 = 1，请求断开 NADV */</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 读回: 0x00000000 */</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AFIO</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MAPR2 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">000003E0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">U</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   /* 非保留位全部写 1，排除掩码问题 */</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 读回: 0x00000000 */</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AFIO</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MAPR  </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">00000001</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">U</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   /* 同一个 AFIO 里的 MAPR，作为对照组 */</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 读回: 0x00000001 */</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>整个 <code>MAPR2</code> 不响应写操作，而同一个 AFIO 里的 <code>MAPR</code>（偏移 <code>0x04</code>）读写正常，因此可以排除 AFIO 时钟未开、总线错误、地址算错这类原因。</p><h4 id="_3-3-两个容易踩的坑" tabindex="-1">3.3 两个容易踩的坑 <a class="header-anchor" href="#_3-3-两个容易踩的坑" aria-label="Permalink to &quot;3.3 两个容易踩的坑&quot;">​</a></h4><p>（1）中文参考手册里查不到 <code>AFIO_MAPR2</code>。<a href="https://cnb.cool/sumu.m/scm-reference-guide/-/git/raw/main/30-STM32%E8%B5%84%E6%96%99/STM32%E4%B8%AD%E6%96%87%E5%8F%82%E8%80%83%E6%89%8B%E5%86%8C_V10.pdf" target="_blank" rel="noreferrer">《STM32 中文参考手册》V10</a> 对应的是 2009 年的 RM0008 英文第 10 版，而 MAPR2（含 <code>FSMC_NADV</code>、TIM9~14 重映射）是之后的版本才补进去的，查这些位必须看英文 V15。手册里搜不到不等于寄存器不存在。</p><p>（2）手册之间说法不一致时，以硅片实测为准。勘误只说“NADV 默认置 1 会与 SDA 冲突”，给出的解法是重映射，从未承诺 <code>FSMC_NADV</code> 位一定写得进去；实测写不进去，属于文档之外的行为，只能当作本片的既成事实记下来。</p><h2 id="三、-方案与实现" tabindex="-1">三、 方案与实现 <a class="header-anchor" href="#三、-方案与实现" aria-label="Permalink to &quot;三、 方案与实现&quot;">​</a></h2><h3 id="_1-方案对比" tabindex="-1">1. 方案对比 <a class="header-anchor" href="#_1-方案对比" aria-label="Permalink to &quot;1. 方案对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方案</th><th>前提</th><th>代价</th></tr></thead><tbody><tr><td>硬件 I2C1 走 PB8/PB9</td><td>飞线把 EEPROM 两脚从 PB6/PB7 挪到 PB8/PB9，并置 <code>I2C1_REMAP</code></td><td>改板，量产不现实</td></tr><tr><td>软件模拟 I2C 走 PB6/PB7</td><td>无，直接位操作</td><td>占 CPU，速率只有几十 kHz</td></tr></tbody></table><p>24C02 容量仅 256 字节、单次读写几毫秒，软件模拟完全够用，于是把驱动固定在软件模拟这条路上。</p><h3 id="_2-工程实现" tabindex="-1">2. 工程实现 <a class="header-anchor" href="#_2-工程实现" aria-label="Permalink to &quot;2. 工程实现&quot;">​</a></h3><p>驱动用宏把两条实现隔离，公共层只依赖“总线层接口”，两份实现各自用 <code>#if</code> 整体包起来，切换只改一个宏。宏为 0 时硬件版文件整份不参与编译，<code>main()</code> 里的 <code>MX_I2C1_Init()</code> 调用也被同一个宏跳过——I2C1 外设既不开时钟也不占引脚。宏定义与结论记录在 <a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/flash-app/Drivers/BSP/EEPROM/bsp_eeprom.h" target="_blank" rel="noreferrer"><code>bsp_eeprom.h</code></a> 的注释块里，软件模拟实现见 <a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/flash-app/Drivers/BSP/EEPROM/bsp_eeprom_sw.c" target="_blank" rel="noreferrer"><code>bsp_eeprom_sw.c</code></a>：</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// flash-app/Drivers/BSP/EEPROM/bsp_eeprom.h</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* 0 = 软件模拟(PB6/PB7 位操作), 1 = 硬件 I2C1 */</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#ifndef</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> BSP_EEPROM_USE_HW_I2C</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> BSP_EEPROM_USE_HW_I2C</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#endif</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>软件模拟的时序细节见 <a href="/scm-docs/sdoc/communication/i2c/126d67bc563d22c0aee96b8e.html">LV010-I2C时序与软件模拟</a>，器件本身的读写流程见同目录的 <a href="./LV010-AT24C02简介.html">LV010-AT24C02简介</a>。</p><h2 id="四、-验证与结论" tabindex="-1">四、 验证与结论 <a class="header-anchor" href="#四、-验证与结论" aria-label="Permalink to &quot;四、 验证与结论&quot;">​</a></h2><h3 id="_1-三组对照实验" tabindex="-1">1. 三组对照实验 <a class="header-anchor" href="#_1-三组对照实验" aria-label="Permalink to &quot;1. 三组对照实验&quot;">​</a></h3><table tabindex="0"><thead><tr><th>实验</th><th>操作</th><th>结果</th></tr></thead><tbody><tr><td>1</td><td>保留 FSMC，把 I2C1 重映射到 PB8/PB9</td><td><code>SB = 1</code>、<code>MSL = 1</code>，START 正常，证明外设无故障</td></tr><tr><td>2</td><td>关掉 FSMC 时钟（清 <code>RCC-&gt;AHBENR</code> 的 <code>FSMCEN</code>）</td><td>立刻恢复正常，START 能发、EEPROM 能读能写</td></tr><tr><td>3</td><td>保留 FSMC，I2C1 用默认的 PB6/PB7</td><td><code>SB</code> 永不置位，SDA/SCL 静止</td></tr></tbody></table><p>实验 1、2 证明 I2C 外设和 EEPROM 都是好的，实验 3 复现问题，变量唯一地锁定在 PB7 的 FSMC 争用上。</p><h3 id="_2-运行验证" tabindex="-1">2. 运行验证 <a class="header-anchor" href="#_2-运行验证" aria-label="Permalink to &quot;2. 运行验证&quot;">​</a></h3><p>换回软件模拟后，用串口 CLI 读 0x0C 起的 8 个字节：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&gt; eeprom read 0x0C 8</span></span>
<span class="line"><span>000C  01 02 03 04 05 06 07 08</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="_3-结论与适用边界" tabindex="-1">3. 结论与适用边界 <a class="header-anchor" href="#_3-结论与适用边界" aria-label="Permalink to &quot;3. 结论与适用边界&quot;">​</a></h3><ul><li>只要 LCD 或外部 SRAM 走 FSMC、而 EEPROM 又焊在 PB6/PB7，硬件 I2C1 就不可用：NADV 的默认高电平与 SDA 直接冲突，且 <code>FSMC_NADV</code> 位在本片写不进去。</li><li>想回到硬件 I2C，必须同时满足两个前提：EEPROM 改到 PB8/PB9（飞线改板），并置 <code>I2C1_REMAP</code>。</li><li>用软件模拟期间，PB6/PB7 不能再当普通 IO 使用。</li></ul><h2 id="五、-延伸与参考" tabindex="-1">五、 延伸与参考 <a class="header-anchor" href="#五、-延伸与参考" aria-label="Permalink to &quot;五、 延伸与参考&quot;">​</a></h2><h3 id="_1-其它-i2c-勘误" tabindex="-1">1. 其它 I2C 勘误 <a class="header-anchor" href="#_1-其它-i2c-勘误" aria-label="Permalink to &quot;1. 其它 I2C 勘误&quot;">​</a></h3><p>将来若真要用硬件 I2C，同一份勘误手册里还有两条会影响驱动写法：</p><table tabindex="0"><thead><tr><th>节号</th><th>内容</th><th>对驱动的影响</th></tr></thead><tbody><tr><td>2.9.1</td><td><code>EV7</code>、<code>EV7_1</code>、<code>EV6_1</code>、<code>EV2</code>、<code>EV8</code>、<code>EV3</code> 必须抢在当前字节传输之前处理</td><td>逐字节查询死等会出问题，官方建议用 DMA，或把 I2C 中断设为最高优先级</td></tr><tr><td>2.9.2</td><td>不完全兼容 SMBus v2.0，对非法字节不发 NACK</td><td>需要上层校验机制（SMBALERT、ARA、主机提醒协议）</td></tr></tbody></table><h3 id="_2-参考资料" tabindex="-1">2. 参考资料 <a class="header-anchor" href="#_2-参考资料" aria-label="Permalink to &quot;2. 参考资料&quot;">​</a></h3><ul><li>勘误手册：<a href="https://cnb.cool/sumu.m/scm-reference-guide/-/git/raw/main/30-STM32%E8%B5%84%E6%96%99/15-STM32%E5%8B%98%E8%AF%AF%E6%89%8B%E5%86%8C/STM32F10xxCDE_Errata_CH_V5.pdf" target="_blank" rel="noreferrer">STM32F10xxCDE_Errata_CH_V5.pdf</a>，引用第 2.4.9、2.9.1、2.9.2 节；同系列的 <code>STM32F10xx8B</code>、<code>STM32F10xx46</code>、<code>STM32F107</code> 三本对应其它容量档，与本板无关，仅存档备查</li><li>参考手册（英文）：<a href="https://cnb.cool/sumu.m/scm-reference-guide/-/git/raw/main/30-STM32%E8%B5%84%E6%96%99/STM32%E8%8B%B1%E6%96%87%E5%8F%82%E8%80%83%E6%89%8B%E5%86%8C_V15.pdf" target="_blank" rel="noreferrer">STM32英文参考手册_V15.pdf</a>，引用第 9.4.7 节（<code>AFIO_MAPR2</code>）、第 9.4.2 节（<code>AFIO_MAPR</code>）、第 19.5.1 节（FSMC 外部存储器接口信号）、第 24 章（I2C 接口）</li><li>参考手册（中文）：<a href="https://cnb.cool/sumu.m/scm-reference-guide/-/git/raw/main/30-STM32%E8%B5%84%E6%96%99/STM32%E4%B8%AD%E6%96%87%E5%8F%82%E8%80%83%E6%89%8B%E5%86%8C_V10.pdf" target="_blank" rel="noreferrer">STM32中文参考手册_V10.pdf</a>，第 19 章 FSMC（该版尚无 <code>AFIO_MAPR2</code>）</li><li>数据手册：<a href="https://cnb.cool/sumu.m/scm-reference-guide/-/git/raw/main/30-STM32%E8%B5%84%E6%96%99/STM32F103xCDE_DS_CH_V5.pdf" target="_blank" rel="noreferrer">STM32F103xCDE_DS_CH_V5.pdf</a>，第 3 章 Pinouts and pin descriptions</li><li>原理图：<a href="https://cnb.cool/sumu.m/scm-reference-guide/-/git/raw/main/30-STM32%E8%B5%84%E6%96%99/01-ATK%E6%88%98%E8%88%B0-V3%E5%BC%80%E5%8F%91%E6%9D%BF%E5%8E%9F%E7%90%86%E5%9B%BE/WarShip%20STM32F1_V3.4_SCH.pdf" target="_blank" rel="noreferrer">WarShip STM32F1_V3.4_SCH.pdf</a>，第 3 页 EEPROM 区</li><li>驱动源码：<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/flash-app/Drivers/BSP/EEPROM/bsp_eeprom.h" target="_blank" rel="noreferrer">bsp_eeprom.h</a>、<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/flash-app/Drivers/BSP/EEPROM/bsp_eeprom_sw.c" target="_blank" rel="noreferrer">bsp_eeprom_sw.c</a>、<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/flash-app/Drivers/BSP/EEPROM/bsp_eeprom_hw.c" target="_blank" rel="noreferrer">bsp_eeprom_hw.c</a></li></ul><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>`,56)])])}const k=e(r,[["render",n]]);export{b as __pageData,k as default};
